/*
 * A256869  Numbers divisible by prime(d+1) for each digit d of their base-9
 *          representation.
 * https://oeis.org/A256869
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 5, u16 n <= 115, u32 n <= 3000, u64 n <= 3000,
 *            u128 n <= 3000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Implements OEIS sequence A256869: numbers divisible by prime(d+1)
   for each digit d of their base‑9 representation. */
/* The sequence is generated by an on‑demand sieve. */

#include <stdlib.h>   /* for malloc, realloc, size_t */
#include <stdbool.h>  /* for bool */

static const uint32_t primes[9] = {2,3,5,7,11,13,17,19,23};

/* lcm_table[mask] = product of primes[d] where mask has bit d set.
   Since these primes are all distinct, the lcm is their product. */
static seq_t lcm_table[512];
static bool lcm_initialized = false;

/* initialise lcm_table once */
static void init_lcm_table(void)
{
    if (lcm_initialized) return;
    for (unsigned mask = 0; mask < 512; ++mask) {
        seq_t prod = 1;
        for (unsigned d = 0; d < 9; ++d) {
            if (mask & (1U << d))
                prod *= (seq_t)primes[d];
        }
        lcm_table[mask] = prod;
    }
    lcm_initialized = true;
}

/* Cache of previously computed terms */
static seq_t *cache      = NULL;
static size_t cache_len  = 0;
static size_t cache_cap  = 0;
static idx_t  last_checked = 0;   /* last candidate examined */

/* append a new term to the cache, resizing if necessary */
static void append_term(seq_t val)
{
    if (cache_len == cache_cap) {
        size_t new_cap = (cache_cap == 0) ? 16 : cache_cap << 1;
        seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        /* Assume realloc succeeds; if it fails, the program will abort on next use. */
        cache = tmp;
        cache_cap = new_cap;
    }
    cache[cache_len++] = val;
}

/* check whether candidate satisfies the property */
static bool satisfies(idx_t cand)
{
    unsigned mask = 0;
    if (cand == 0) {
        mask = 1U << 0;   /* digit 0 only */
    } else {
        idx_t tmp = cand;
        while (tmp) {
            unsigned d = (unsigned)(tmp % 9U);
            mask |= 1U << d;
            tmp /= 9U;
        }
    }
    seq_t lcm = lcm_table[mask];
    return ((seq_t)cand) % lcm == 0;
}

/* Public API */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;   /* safety guard, off‑by‑one protection */

    init_lcm_table();

    /* initialise cache with the first term if necessary */
    if (cache_len == 0) {
        append_term((seq_t)0);      /* a(1) = 0 */
        last_checked = 0;
    }

    /* generate further terms until we have n of them */
    while (cache_len < n) {
        ++last_checked;
        if (satisfies(last_checked))
            append_term((seq_t)last_checked);
    }

    return cache[n - 1];
}
